package com.nigson.commerce.pricing;
import java.util.*;import java.time.*;import java.math.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionTemplate;
import com.nigson.commerce.platform.*;import com.nigson.commerce.market.*;import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.*;import com.nigson.shared.security.ActorAssertion;import tools.jackson.databind.JsonNode;
/** One owner-local commercial-price transaction; no provider calls or historical book mutation. */
public final class ProductPrices {
 public record Value(UUID bookId,long version,String unitAmount,String minimumQuantity,boolean legacy){}
 public record View(UUID marketId,long marketVersion,Value retail,Value wholesale,Value distributor){}
 private final JdbcTemplate jdbc;private final PricingAuthority authority;private final PriceBookService books;private final MarketService markets;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final TransactionTemplate reads;
 public ProductPrices(JdbcTemplate jdbc,PricingAuthority authority,PriceBookService books,MarketService markets,PlatformStore commands,AuditWriter audit,Clock clock,org.springframework.transaction.PlatformTransactionManager manager){this.jdbc=jdbc;this.authority=authority;this.books=books;this.markets=markets;this.commands=commands;this.audit=audit;this.clock=clock;reads=new TransactionTemplate(manager);reads.setReadOnly(true);reads.setIsolationLevel(4);reads.setTimeout(3);}
 private UUID market(){var ids=jdbc.query("SELECT id FROM commerce.market WHERE code='NG' AND currency_code='NGN'",(r,n)->r.getObject(1,UUID.class));if(ids.size()!=1)throw PricingValues.rule();return ids.getFirst();}
 public View get(ActorAssertion.Actor actor,UUID sku){authority.requirePriceBook(actor,"SALES");return reads.execute(s->{authority.requirePriceBook(actor,"SALES");return snapshot(sku,market(),false);});}
 private View snapshot(UUID sku,UUID market,boolean lock){var scale=jdbc.query("SELECT s.quantity_scale FROM commerce.sku s JOIN commerce.product p ON p.id=s.product_id WHERE s.id=? AND s.active AND s.deleted_at IS NULL AND p.deleted_at IS NULL"+(lock?" FOR SHARE OF p,s":""),(r,n)->r.getInt(1),sku);if(scale.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var m=jdbc.queryForMap("SELECT retail_price_book_id,version FROM commerce.market WHERE id=?"+(lock?" FOR UPDATE":""),market);UUID retail=(UUID)m.get("retail_price_book_id");return new View(market,((Number)m.get("version")).longValue(),value(sku,market,"RETAIL",retail),value(sku,market,"WHOLESALE",null),value(sku,market,"DISTRIBUTOR",null));}
 private Value value(UUID sku,UUID market,String segment,UUID book){long version=0;boolean legacy=false;
  if(!segment.equals("RETAIL")&&authority.phase()<3)return new Value(null,0,null,null,false);if(!segment.equals("RETAIL")){var bindings=jdbc.queryForList("SELECT price_book_id,version FROM commerce.standard_sku_price WHERE market_id=? AND sku_id=? AND segment=?",market,sku,segment);if(!bindings.isEmpty()){book=(UUID)bindings.getFirst().get("price_book_id");version=((Number)bindings.getFirst().get("version")).longValue();if(book==null)return new Value(null,version,null,null,false);}else{legacy=true;var ids=jdbc.query("SELECT b.id FROM commerce.price_book b JOIN commerce.price_entry e ON e.price_book_id=b.id WHERE e.sku_id=? AND b.segment=? AND b.currency_code='NGN' AND b.active AND b.effective_from<=? AND (b.effective_until IS NULL OR b.effective_until>?) ORDER BY b.created_at DESC,b.id DESC LIMIT 1",(r,n)->r.getObject(1,UUID.class),sku,segment,java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant()));book=ids.isEmpty()?null:ids.getFirst();}}
  if(book==null)return new Value(null,version,null,null,legacy);var rows=jdbc.query("SELECT unit_amount,minimum_quantity FROM commerce.price_entry WHERE price_book_id=? AND sku_id=? ORDER BY minimum_quantity LIMIT 1",(r,n)->new String[]{PricingValues.minor(PricingValues.decimal(r.getBigDecimal(1)),2).toPlainString(),PricingValues.decimal(r.getBigDecimal(2))},book,sku);return rows.isEmpty()?new Value(book,version,null,null,legacy):new Value(book,version,rows.getFirst()[0],rows.getFirst()[1],legacy);}
 public static View parse(JsonNode n){closed(n,Set.of("marketId","marketVersion","retail","wholesale","distributor"));if(!n.path("marketVersion").isIntegralNumber()||!n.path("marketVersion").canConvertToLong()||n.path("marketVersion").asLong()<0)throw ApiValues.invalid();return new View(ApiValues.uuid(n.path("marketId").asString()),n.path("marketVersion").asLong(),parseValue(n.path("retail")),parseValue(n.path("wholesale")),parseValue(n.path("distributor")));}
 private static void closed(JsonNode n,Set<String> fields){if(!n.isObject()||!n.propertyNames().equals(fields))throw ApiValues.invalid();}
 private static Value parseValue(JsonNode n){closed(n,Set.of("bookId","version","unitAmount","minimumQuantity","legacy"));if(!n.path("version").isIntegralNumber()||!n.path("version").canConvertToLong()||n.path("version").asLong()<0||!n.path("legacy").isBoolean())throw ApiValues.invalid();if(!n.path("unitAmount").isNull()&&!n.path("unitAmount").isString()||!n.path("minimumQuantity").isNull()&&!n.path("minimumQuantity").isString())throw ApiValues.invalid();UUID book=n.path("bookId").isNull()?null:ApiValues.uuid(n.path("bookId").asString());String amount=n.path("unitAmount").isNull()?null:PricingValues.minor(n.path("unitAmount").asString(),2).toPlainString(),minimum=n.path("minimumQuantity").isNull()?null:PricingValues.decimal(ApiValues.quantity(n.path("minimumQuantity").asString()));if((amount==null)!=(minimum==null))throw ApiValues.invalid();return new Value(book,n.path("version").asLong(),amount,minimum,n.path("legacy").asBoolean());}
 private String key(String key,String suffix){return EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("key",key,"step",suffix)));}
 private PricingValues.Book publish(ActorAssertion.Actor actor,String segment,List<PricingValues.Entry> entries,String key,UUID corr){return publish(actor,segment,entries,key,corr,null);}
 private PricingValues.Book publish(ActorAssertion.Actor actor,String segment,List<PricingValues.Entry> entries,String key,UUID corr,Instant until){var draft=books.create(actor,new PricingValues.Input("NG-"+segment+"-"+UUID.randomUUID(),"NGN",segment,clock.instant(),until,entries),key(key,segment+"-create"),corr);return books.activate(actor,draft.id(),draft.version(),"Product editor standard commercial price update",key(key,segment+"-activate"),corr);}
 private boolean changed(Value a,Value b){return !Objects.equals(a.unitAmount(),b.unitAmount())||!Objects.equals(a.minimumQuantity(),b.minimumQuantity());}
 private void expected(Value actual,Value expected){if(!Objects.equals(actual.bookId(),expected.bookId())||actual.version()!=expected.version())throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);}
 public View save(ActorAssertion.Actor actor,UUID sku,View input,String key,UUID corr){authority.requirePriceBook(actor,"FINANCE");authority.requirePriceBook(actor,"SALES");ApiValues.idempotencyKey(key);if(corr==null||input.retail().unitAmount()==null)throw ApiValues.invalid();var request=EventCodec.JSON.valueToTree(Map.of("sku",sku,"prices",input));var response=commands.executeLocal(actor.party().toString(),"API-221",key,request,db->{authority.stabilizePriceBook(actor,"FINANCE");authority.stabilizePriceBook(actor,"SALES");jdbc.query("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",(r,n)->1,"standard-prices:"+sku);if(!market().equals(input.marketId()))throw ApiValues.invalid();var before=snapshot(sku,input.marketId(),true);if(before.marketVersion()!=input.marketVersion())throw new Problem.Failure(ProblemCode.VERSION_MISMATCH);expected(before.retail(),input.retail());expected(before.wholesale(),input.wholesale());expected(before.distributor(),input.distributor());
  String retailMinimum=before.retail().minimumQuantity()==null?jdbc.queryForObject("SELECT pack_size::text FROM commerce.sku WHERE id=?",String.class,sku):before.retail().minimumQuantity();if(new BigDecimal(retailMinimum).compareTo(new BigDecimal(input.retail().minimumQuantity()))!=0)throw ApiValues.invalid();if(changed(before.retail(),input.retail())){if(before.retail().bookId()==null)throw PricingValues.rule();var entries=jdbc.query("SELECT sku_id,minimum_quantity,unit_amount FROM commerce.price_entry WHERE price_book_id=? ORDER BY sku_id,minimum_quantity LIMIT 101",(r,n)->new PricingValues.Entry(r.getObject(1,UUID.class),PricingValues.decimal(r.getBigDecimal(2)),PricingValues.minor(PricingValues.decimal(r.getBigDecimal(3)),2).toPlainString()),before.retail().bookId());if(entries.size()>100)throw PricingValues.rule();var copy=new ArrayList<PricingValues.Entry>();for(var e:entries)if(!e.skuId().equals(sku)||!e.minimumQuantity().equals(input.retail().minimumQuantity()))copy.add(e);copy.add(new PricingValues.Entry(sku,input.retail().minimumQuantity(),input.retail().unitAmount()));var until=jdbc.queryForObject("SELECT effective_until FROM commerce.price_book WHERE id=?",java.sql.Timestamp.class,before.retail().bookId());var book=publish(actor,"RETAIL",copy,key,corr,until==null?null:until.toInstant());markets.book(actor,input.marketId(),before.marketVersion(),new MarketValues.Book(book.id(),"Product editor retail selling price update"),key(key,"retail-bind"),corr);}
  bind(actor,sku,input.marketId(),"WHOLESALE",before.wholesale(),input.wholesale(),key,corr);bind(actor,sku,input.marketId(),"DISTRIBUTOR",before.distributor(),input.distributor(),key,corr);var after=snapshot(sku,input.marketId(),false);audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.PRICE_ASSIGNMENT,AuditValues.Resource.SKU,sku,corr,AuditValues.Reason.CONFIGURATION_CHANGE,Map.of("marketVersion",before.marketVersion()),Map.of("marketVersion",after.marketVersion(),"standardPrices",true),null);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(after),sku);});return EventCodec.JSON.treeToValue(response.body(),View.class);}
 private void bind(ActorAssertion.Actor actor,UUID sku,UUID market,String segment,Value before,Value next,String key,UUID corr){if(!before.legacy()&&!changed(before,next))return;if(authority.phase()<3)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.price_assignment a JOIN commerce.price_book b ON b.id=a.price_book_id JOIN commerce.price_entry e ON e.price_book_id=b.id WHERE a.active AND a.market_id=? AND b.segment=? AND e.sku_id=?)",Boolean.class,market,segment,sku)))throw new Problem.Failure(ProblemCode.PRICING_RULE_VIOLATION,List.of(new Problem.Violation(segment,"CUSTOM_PRICING_CONFLICT","Existing organization-specific pricing must be reviewed before this SKU can use standard "+segment+" pricing.")));UUID book=next.unitAmount()==null?null:publish(actor,segment,List.of(new PricingValues.Entry(sku,next.minimumQuantity(),next.unitAmount())),key,corr).id();jdbc.update("INSERT INTO commerce.standard_sku_price(id,created_by,updated_by,market_id,sku_id,segment,price_book_id) VALUES (?,?,?,?,?,?,?) ON CONFLICT(market_id,sku_id,segment) DO UPDATE SET price_book_id=EXCLUDED.price_book_id,version=commerce.standard_sku_price.version+1,updated_at=now(),updated_by=EXCLUDED.updated_by",EventCodec.uuid7(clock.instant()),actor.party().toString(),actor.party().toString(),market,sku,segment,book);}
}
